/**
 * The prompt-submit hook (ADR-0065, plan §5.8 H-PROMPT / P17, rounds 2–4),
 * written once for every host. `prism-mcp --hook prompt` runs it for
 * opencode and the daemon-off path; the Claude plugin runs a dependency-free
 * bundle of this file (`packages/plugin/hooks/prompt-hook.mjs`, generated by
 * `bun run gen:prompt-hook`; `prompt-hook.contract.test.ts` holds the two to
 * the same answers), so a prompt costs one Node process, not two.
 *
 * Quick part first: the lens (once per session) comes from the lens store and
 * needs no index. Only a change prompt then asks for the short block of files
 * Prism is sure of (`files.call`: the warm daemon's `/v1/prompt`, or an
 * in-process index when the daemon is off). On a deadline or a silent daemon
 * the block is dropped and the lens still goes out.
 */

import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { classifyPrompt } from "./classify-prompt.js";
import type { PrismError } from "./errors.js";
import { recordEvent } from "./events.js";
import { chooseLensDetailed } from "./lens-route.js";
import {
  applyDefaultProcedures,
  DEFAULT_LENSES,
  lensProcedure,
  readLensStore,
} from "./lens-store.js";
import {
  buildPromptPack,
  lensLabel,
  promptSummaryLine,
  type PromptPackLens,
  widensScope,
} from "./prepare-context.js";
import { workspacePrismDir } from "./prism-home.js";
import {
  readSessionStore,
  recordSent,
  writeSessionStore,
} from "./session-store.js";

export type PromptContextRequest = {
  readonly prompt: string;
  readonly sessionId?: string;
};

export type PromptContext = {
  /** The text to inject, or null: say nothing. */
  readonly text: string | null;
  readonly reason: string;
  /** Files shown for the first time this session. */
  readonly files: number;
  /**
   * Those files with their content key. The hook records them in the session
   * store only once the block is delivered (`rememberShown`): a block that
   * missed the deadline must not count as "same as before" next turn.
   */
  readonly shown?: readonly { readonly path: string; readonly hash: string }[];
  /** The prompt named a file Prism would list (quiet before-edit notes). */
  readonly named: boolean;
  /** What the block held, in words, for the line the user sees (round 4). */
  readonly summary?: readonly string[];
};

/** Default wall budget for auto-prepare (plan P17): one daemon call. */
export const AUTO_PREPARE_MS = 900;

/** Prompt kinds that may get a pack or a lens; the rest say nothing. */
export const PROMPT_KINDS: readonly string[] = ["change", "review", "question"];

/** §4.6 / H-PROMPT: the line an unsupported repository gets instead of a pack. */
export const UNSUPPORTED_LANGUAGE_NOTE =
  "Prism: this repository's language is not supported in 2.0; no pack.";

function degraded(
  event: string,
  error: unknown,
  root: string,
  env: NodeJS.ProcessEnv,
): void {
  recordEvent(
    {
      event,
      outcome: "degraded",
      reason: error instanceof Error ? error.message : String(error),
      workspace: root,
    },
    { env },
  );
}

/**
 * True the first time `what` is marked for this session, false after. Keyed
 * by a hash of the session id, so two sessions never share a mark.
 */
export function markSessionOnce(
  root: string,
  sessionId: string,
  what: string,
  env: NodeJS.ProcessEnv,
): boolean {
  const key = createHash("sha256").update(sessionId).digest("hex").slice(0, 24);
  const path = join(
    workspacePrismDir(root, env),
    "hooks",
    "once",
    `${key}.json`,
  );
  let marks: string[] = [];
  try {
    marks = JSON.parse(readFileSync(path, "utf8")) as string[];
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT")
      degraded("prompt.session_marks", error, root, env);
  }
  if (!Array.isArray(marks)) marks = [];
  if (marks.includes(what)) return false;
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, JSON.stringify([...marks, what]));
  return true;
}

/**
 * The lens for this prompt, once per session (plan §5.3), and again when a
 * follow-up widens the scope ("everything", "anywhere"; round 4). A lens the
 * prompt names (or a custom trigger) applies to any prompt; Architect and QA
 * to a change, a review or a question; Dev, the default, to a change only.
 * Reads only the lens store, so the hook answers it while an index runs.
 */
export async function promptLens(
  root: string,
  prompt: string,
  kind: string,
  sessionId: string | undefined,
  env: NodeJS.ProcessEnv,
): Promise<PromptPackLens | undefined> {
  const store = await readLensStore(root, env);
  const lenses = applyDefaultProcedures(
    store.lenses.length > 0 ? store.lenses : DEFAULT_LENSES,
  );
  const choice = chooseLensDetailed(prompt, lenses);
  if (!choice) return undefined;
  const applies =
    choice.by === "named" || choice.by === "trigger"
      ? true
      : choice.by === "default"
        ? kind === "change"
        : kind === "change" || kind === "review" || kind === "question";
  if (!applies) return undefined;
  const first =
    !sessionId ||
    markSessionOnce(root, sessionId, `lens:${choice.lens.id}`, env);
  if (!first && !widensScope(prompt)) return undefined;
  return {
    id: choice.lens.id,
    name: choice.lens.name,
    procedure: lensProcedure(choice.lens),
    ...(choice.conflict ? { conflict: choice.conflict } : {}),
  };
}

/** Record the files a delivered block showed (P4 session store). */
export function rememberShown(
  sessionId: string,
  shown: NonNullable<PromptContext["shown"]>,
  env: NodeJS.ProcessEnv,
): void {
  if (shown.length === 0) return;
  let store = readSessionStore(sessionId, env);
  for (const file of shown)
    store = recordSent(store, file.path, file.hash, "file");
  writeSessionStore(store, env);
}

/**
 * The prompt named the files Prism would list (token fix 4): the plugin's
 * before-edit "not in Prism's pack" nudge stays quiet for this session.
 */
export function markLiteSession(
  root: string,
  sessionId: string,
  env: NodeJS.ProcessEnv,
): void {
  const path = join(workspacePrismDir(root, env), "hooks", "lite.json");
  let ids: unknown = [];
  try {
    ids = JSON.parse(readFileSync(path, "utf8"));
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT")
      degraded("prompt.lite_session", error, root, env);
  }
  const list = Array.isArray(ids) ? (ids as string[]) : [];
  if (list.includes(sessionId)) return;
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, JSON.stringify([...list.slice(-50), sessionId]));
}

/** What asking for the file block came to (the daemon client's shape). */
export type PromptFilesOutcome =
  | { readonly kind: "ok"; readonly value: PromptContext }
  | { readonly kind: "error"; readonly error: PrismError }
  | { readonly kind: "unavailable"; readonly reason: string };

export type PromptFiles = {
  /** Ask for the file block; `budgetMs` is what is left of the limit. */
  readonly call: (
    request: PromptContextRequest,
    budgetMs: number,
  ) => Promise<PromptFilesOutcome>;
  /**
   * `daemon`: skipped when under 50 ms remain, and an unavailable daemon
   * means no block (P17 / HOOK-P2: never index in-process while it is on).
   */
  readonly via: "daemon" | "in-process";
};

/**
 * Run the prompt hook on the host's input (`prompt`, `session_id`). Returns
 * the hook JSON; an empty object means "say nothing".
 */
export async function runPromptHook(
  input: Record<string, unknown>,
  options: {
    readonly root: string;
    readonly files: PromptFiles;
    readonly env?: NodeJS.ProcessEnv;
    readonly now?: () => number;
    /** When the hook's budget started (the process's own start). */
    readonly startedAt?: number;
    /** The wall budget; default `PRISM_AUTOPREPARE_MS` or AUTO_PREPARE_MS. */
    readonly limitMs?: number;
    /** Where the one-line reason goes (default stderr). */
    readonly log?: (line: string) => void;
  },
): Promise<Record<string, unknown>> {
  const env = options.env ?? process.env;
  const now = options.now ?? Date.now;
  const started = options.startedAt ?? now();
  const root = resolve(options.root);
  const log =
    options.log ??
    ((line: string) => process.stderr.write(`prism-mcp: ${line}\n`));
  const say = (
    reason: string,
    event: string,
    outcome: "skipped" | "ok" = "skipped",
  ): void => {
    log(`auto-prepare ${reason}`);
    recordEvent(
      { event, outcome, reason, workspace: root, durationMs: now() - started },
      { env },
    );
  };
  const mode = env.PRISM_AUTOPREPARE;
  if (mode === "0" || mode === "off") {
    say("PRISM_AUTOPREPARE off", "prompt.skipped");
    return {};
  }
  const prompt = typeof input.prompt === "string" ? input.prompt : "";
  const kind = classifyPrompt(prompt).kind;
  if (!PROMPT_KINDS.includes(kind)) {
    say(`not a change request (${kind})`, "prompt.skipped");
    return {};
  }
  const limitMs =
    options.limitMs ?? Number(env.PRISM_AUTOPREPARE_MS ?? AUTO_PREPARE_MS);
  const sessionId =
    typeof input.session_id === "string" && input.session_id
      ? input.session_id
      : undefined;
  let lensText: string | null = null;
  let lensReason = "";
  let lensName: string | null = null;
  const reply = (
    parts: readonly (string | null)[],
    reason: string,
    summary: readonly string[] = [],
  ) => {
    const text = parts.filter(Boolean).join("\n");
    // The user sees one line for whatever Prism gave the agent. A change
    // prompt always gets it; a question or review only with a lens.
    const line = promptSummaryLine(
      lensName && lensText ? [lensName, ...summary] : summary,
      kind === "change",
    );
    const shown = line ? { systemMessage: line } : {};
    if (!text) {
      say(`said nothing (${reason})`, "prompt.quiet");
      return shown;
    }
    say(`injected in ${now() - started}ms: ${reason}`, "prompt.injected", "ok");
    return {
      ...shown,
      hookSpecificOutput: {
        hookEventName: "UserPromptSubmit",
        additionalContext: text,
      },
    };
  };

  try {
    const lens = await promptLens(root, prompt, kind, sessionId, env);
    if (lens) {
      lensText = buildPromptPack({ prep: null, prompt, lens }).text;
      lensReason = `; lens ${lens.id}`;
      lensName = lensLabel(lens.name);
    }
  } catch (error) {
    say(
      `lens skipped (${error instanceof Error ? error.message : String(error)})`,
      "prompt.lens",
    );
  }
  if (kind !== "change") return reply([lensText], `${kind}${lensReason}`);

  const request: PromptContextRequest = {
    prompt,
    ...(sessionId ? { sessionId } : {}),
  };
  const busy = (why: string) => {
    say(why, why.startsWith("no time") ? "prompt.deadline" : "prompt.daemon");
    return reply([lensText], `no file block (deadline)${lensReason}`, [
      "files skipped (index busy)",
    ]);
  };
  const budget = limitMs - (now() - started);
  if (options.files.via === "daemon" && budget < 50)
    return busy("no time left for the file block");
  const outcome = await options.files.call(request, budget);
  if (outcome.kind === "unavailable")
    return busy(`deadline (${outcome.reason})`);
  if (outcome.kind === "error") {
    const details = outcome.error.details as { reason?: unknown } | undefined;
    if (details?.reason === "language") {
      // §4.6: an unsupported-language repo gets one line, once per session.
      const note =
        !sessionId || markSessionOnce(root, sessionId, "language", env)
          ? UNSUPPORTED_LANGUAGE_NOTE
          : null;
      return reply([note], "unsupported language", ["language not supported"]);
    }
    say(`skipped (${outcome.error.message})`, "prompt.skipped");
    return reply([lensText], `no file block${lensReason}`);
  }
  const answer = outcome.value;
  const elapsed = now() - started;
  if (elapsed > limitMs) {
    say(`deadline (took ${elapsed}ms, over ${limitMs}ms)`, "prompt.deadline");
    return reply([lensText], `no file block (deadline)${lensReason}`, [
      "files skipped (index busy)",
    ]);
  }
  if (sessionId && answer.text) {
    try {
      rememberShown(sessionId, answer.shown ?? [], env);
      if (answer.named) markLiteSession(root, sessionId, env);
    } catch (error) {
      say(
        `session memory not saved (${error instanceof Error ? error.message : String(error)})`,
        "prompt.session_store",
      );
    }
  }
  return reply(
    [answer.text, lensText],
    `${answer.reason} (${options.files.via})${lensReason}`,
    answer.summary ?? [],
  );
}
